    'w.delen': "ділитися, поширювати",
    'w.screenshot': "скриншот",
    's.gossip.1': "Я не пліткую про колег.",
    's.gossip.2': "Я не викладаю фото з роботи в інтернет.",
    's.gossip.3': { m: 'Краще скажи це мені самому.', f: 'Краще скажи це мені самій.', x: 'Краще скажи це мені особисто.' }, // x: nieuw, nalezen // nagelezen AI 28 nov
    'c.gossip.q': { m: 'Ти чув, що зробив Марк?', f: 'Ти чула, що зробив Марк?', x: 'Знаєш, що зробив Марк?' }, // x: nieuw, nalezen // nagelezen AI 28 nov
    'c.gossip.a': "Ні, і я волію про нього не говорити.",
    'l.boundaries': "Перетнути межу",
    'w.aanraken': "торкатися",
