    'w.afval': "відходи, сміття", // nieuw, nalezen // nagelezen AI 28 nov
    'w.container': "контейнер (дуже великий бак для відходів)", // nieuw, nalezen // nagelezen AI 28 nov
    'w.struikelen': "спіткнутися (впасти через щось)", // nieuw, nalezen // nagelezen AI 28 nov
    's.siteday.1': "Відходи кидають у контейнер.", // nieuw, nalezen // nagelezen AI 28 nov
    's.siteday.2': "Виконроб у побутівці.", // nieuw, nalezen // nagelezen AI 28 nov
