    's.shoptrouble.1': "Я покличу керівника магазину.", // nieuw, nalezen // nagelezen AI 28 nov
    's.shoptrouble.2': "Не кричіть, будь ласка.", // nieuw, nalezen // nagelezen AI 28 nov
