    'w.afplakken': "заклеювати (закривати край стрічкою)", // nieuw, nalezen // nagelezen AI 28 nov
    's.prep.1': "Спочатку зішкреб стару фарбу.", // nieuw, nalezen // nagelezen AI 28 nov
    's.prep.2': "Зашліфуй дерево, щоб було гладке.", // nieuw, nalezen // nagelezen AI 28 nov
    's.prep.3': "Зміти пил щіточкою.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.prep.q': "Можна вже фарбувати?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.prep.a': "Ні, спочатку зашліфувати й замазати дірку.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.prep': "Добра фарбувальна робота починається до фарби", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.b': "Фарба погано тримається на бруді, пилу чи старій фарбі, що відстає. Тому спочатку зішкреб скребком фарбу, що відстає. Дірки замаж шпаклівкою за допомогою шпателя, і дай шпаклівці висохнути. Потім зашліфуй, щоб було гладко. Після шліфування зміти пил щіточкою, і з країв теж. Наостанок заклей те, що має залишитися чистим, наприклад вікна й розетки. Від шліфування буває дрібний пил: носи маску від пилу і запитай, яку саме. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.p': "Спочатку шліфувати, потім фарбувати.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.s': { m: "Ти зашліфував двері. На них ще є пил. Колега хоче фарбувати вже зараз. Що ти зробиш?", f: "Ти зашліфувала двері. На них ще є пил. Колега хоче фарбувати вже зараз. Що ти зробиш?", x: "Двері вже зашліфовано. На них ще є пил. Колега хоче фарбувати вже зараз. Що ти зробиш?" }, // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.o1': "Спочатку змітеш пил щіточкою.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.o2': "Дозволиш фарбувати: фарба закриє пил.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.o3': "Витреш пил рукою.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.prep.w': "Фарба на пилу погано тримається. Пізніше вона відпадає пластівцями, і тоді всю роботу треба робити знову.", // nieuw, nalezen // nagelezen AI 22 nov
