    'w.schimmel': "пліснява", // nieuw, nalezen // nagelezen AI 28 nov
    'w.ontsmettingsmat': "дезінфекційний килимок (ти стаєш на нього біля дверей)", // nieuw, nalezen // nagelezen AI 28 nov
    's.pests.1': "На цьому листку попелиця.", // nieuw, nalezen // nagelezen AI 28 nov
    's.pests.2': "Повісь клейову пастку над рослинами.", // nieuw, nalezen // nagelezen AI 28 nov
    's.pests.3': "Пройди по дезінфекційному килимку.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pests.q': "Можна мені вбити цю осу?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pests.a': "Ні, це оса-наїзник. Вона нам допомагає.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pests': "Не переноси хвороби з ряду в ряд", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.b': "Хвороба або шкідник швидко поширюється в теплиці. Ти можеш перенести їх на руках, одязі й інструментах. Тому біля кожних дверей проходь по дезінфекційному килимку і мий руки, коли йдеш в іншу частину теплиці. Починай роботу в здорових рядах, а закінчуй у хворих. Бачиш на рослині комах, плями або плісняву? Не торкайся її, а скажи керівнику, де це. Деякі комахи в теплиці — помічники: не чіпай їх. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.p': "Тут пліснява.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.s': "Ти бачиш сіру плісняву на кількох рослинах у своєму ряду. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.o1': "Скажеш керівнику, де це.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.o2': "Обірвеш погані листки й працюватимеш далі.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.o3': "Нічого не скажеш: це лише кілька рослин.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.pests.w': "Пліснява швидко поширюється. Керівник знає, що робити і з чого почати.", // nieuw, nalezen // nagelezen AI 22 nov
    'u.carservice': "Шини, мастило й гальма", // nieuw, nalezen // nagelezen AI 28 nov
