    'c.brakes.q': "Гальмівний диск теж треба міняти?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.brakes.a': "Так, він занадто тонкий.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.brakes': "Гальма: перевір двічі", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.b': "Гальма зберігають людям життя. Тому працюй спокійно і перевіряй свою роботу двічі. Після нових колодок або дисків кілька разів натисни педаль гальма, перш ніж авто рушить: перше натискання часто йде занадто глибоко. Гальмівна рідина шкодить шкірі й фарбі: одягни рукавиці й одразу витирай краплі. Не здувай гальмівний пил стисненим повітрям: чисть його очисником гальм і ганчіркою. Перш ніж авто поїде, перевір кожен ліхтар, також стоп-сигнали.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.p': "Я кілька разів натискаю педаль гальма.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.s': { m: "Ти поставив нові гальмівні колодки. Авто має виїхати надвір. Що ти зробиш?", f: "Ти поставила нові гальмівні колодки. Авто має виїхати надвір. Що ти зробиш?", x: "Нові гальмівні колодки вже встановлено. Авто має виїхати надвір. Що ти зробиш?" }, // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.o1': "Кілька разів натиснеш педаль гальма.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.o2': "Одразу виїдеш на ньому надвір.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.o3': "Виштовхнеш його без перевірки.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.brakes.w': "Після нових колодок педаль першого разу може піти занадто глибоко. Тоді авто не зупиниться.", // nieuw, nalezen // nagelezen AI 22 nov
