    's.pruning.1': "Обріж кущі вздовж доріжки.", // nieuw, nalezen // nagelezen AI 28 nov
    's.pruning.2': "Ця гілка суха. Відпиляй її.", // nieuw, nalezen // nagelezen AI 28 nov
    's.pruning.3': "Склади гілки в купу.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.q': "Які гілки треба зрізати?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.a': "Лише сухі гілки.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning': "Рівний зріз загоюється найкраще", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.b': "Обрізай гострим, чистим секатором. Рівний зріз швидко загоюється; рвана гілка хворіє. Зрізай трохи вище бруньки або бічної гілки і не залишай довгого шматка. Спершу зріж сухі й зламані гілки. Тримай другу руку подалі від лез. Носи рукавиці: деякі рослини мають колючки або від них червоніє шкіра. Після роботи почисть секатор.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.p': "Де мені різати?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.s': "Твій секатор тупий. Він рве гілки. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.o1': "Попросиш гострий секатор.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.o2': "Сильніше потягнеш гілку.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.o3': "Працюватимеш далі: це ж лише кущ.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.pruning.w': "Тупий секатор рве гілку. Рослина хворіє, а тобі важче працювати.", // nieuw, nalezen // nagelezen AI 28 nov
