    's.chainsaw.1': "Одягни захисні штани для пили.", // nieuw, nalezen // nagelezen AI 28 nov
    's.chainsaw.2': "Здуй листя в купу.", // nieuw, nalezen // nagelezen AI 28 nov
    's.chainsaw.3': "Заправляй, лише коли двигун холодний.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.q': "Можна мені працювати бензопилою?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.a': "Ще ні. Спершу ти пройдеш курс.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw': "Бензопила лише після навчання", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.b': "Бензопила — один із найнебезпечніших інструментів у роботі з зеленими насадженнями. Працюй нею, лише коли в тебе вже був курс і керівник каже, що можна. Завжди носи захисні штани для пили, каску із захисним щитком і захистом слуху, рукавиці й захисні черевики. Ніколи не працюй бензопилою наодинці. Тримай її обома руками і ніколи не пиляй вище плечей. З повітродувкою: ніколи не дми в бік людей, авто чи відчинених вікон. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.p': { m: "Я ще не проходив курсу для цього.", f: "Я ще не проходила курсу для цього.", x: "У мене ще не було курсу для цього." }, // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.s': "Колега каже: «Візьми бензопилу, це легко». У тебе ніколи не було курсу. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.o1': "Скажеш, що в тебе ще не було курсу.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.chainsaw.o2': "Обережно спробуєш, лише один раз.", // nieuw, nalezen // nagelezen AI 28 nov
