    'w.berm': "узбіччя (трава біля дороги)", // nieuw, nalezen // nagelezen AI 28 nov
    's.roadside.1': "Одягни жилет. Ми працюємо біля дороги.", // nieuw, nalezen // nagelezen AI 28 nov
