    's.reception.1': "Доброго ранку, чим можу допомогти?", // nieuw, nalezen // nagelezen AI 28 nov
    's.reception.2': "Я вас з’єдную.", // nieuw, nalezen // nagelezen AI 28 nov
    's.reception.3': "Присядьте, будь ласка, у зоні очікування.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.q': "У мене зустріч із пані Янсен.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.a': "Хвилинку. Я їй зараз подзвоню.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception': "Ти — перше обличчя", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.b': "На рецепції ти перша людина, яку зустрічає відвідувач. Підніми очі, усміхнися і привітайся, навіть коли ти розмовляєш по телефону. Звертайся до відвідувачів на «u» (на «Ви»). Відповідай на дзвінок назвою фірми і своїм іменем. Не знаєш відповіді? Так і скажи і знайди когось, хто знає. Ніколи не давай незнайомим людям імена, номери телефонів чи кімнати працівників.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.p': "Доброго ранку, чим я можу вам допомогти?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.s': "Ти розмовляєш по телефону. До стійки підходить відвідувач і чекає. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.o1': "Піднімеш очі й покажеш, що скоро підійдеш.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.o2': "Закінчиш розмову, не піднімаючи очей.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.o3': "Одразу покладеш слухавку.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.reception.w': "Відвідувач, якого помітили, чекає спокійно. Відвідувач, якого не помітили, почувається небажаним.", // nieuw, nalezen // nagelezen AI 28 nov
    'l.visitors': "Прийом відвідувачів", // nieuw, nalezen // nagelezen AI 28 nov
    'w.bezoekerspasje': "перепустка для відвідувача", // nieuw, nalezen // nagelezen AI 28 nov
    'w.lift': "ліфт", // nieuw, nalezen // nagelezen AI 28 nov
