    's.coldroom.1': "У морозильній камері мінус вісімнадцять градусів.", // nieuw, nalezen // nagelezen AI 28 nov
    's.coldroom.2': "Одразу постав м’ясо в холодильну камеру.", // nieuw, nalezen // nagelezen AI 28 nov
