    's.hazardous.1': "Постав фарбу до хімічних відходів.", // nieuw, nalezen // nagelezen AI 28 nov
    's.hazardous.2': "Ця пляшка протікає. Бери її в рукавицях.", // nieuw, nalezen // nagelezen AI 28 nov
