    's.grouprules.1': { m: "Я ментор Лізи.", f: "Я менторка Лізи.", x: "Ліза — моя підопічна." }, // nieuw, nalezen // nagelezen AI 28 nov
    's.grouprules.2': "Колега завжди може нас бачити чи чути.", // nieuw, nalezen // nagelezen AI 28 nov
    's.grouprules.3': "Я хвилююся за Даана.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.grouprules.q': { m: "Можна мені вийти з групою надвір самому?", f: "Можна мені вийти з групою надвір самій?", x: "Можна мені вийти з групою надвір без колег?" }, // nieuw, nalezen // nagelezen AI 28 nov
    'c.grouprules.a': "Так, але спершу скажи колезі.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.grouprules': "Ніколи наодинці поза полем зору", // nieuw, nalezen // nagelezen AI 28 nov
    'c.grouprules.b': "У дитячому садку інший дорослий завжди повинен мати змогу бачити чи чути тебе, коли ти з дітьми. Це захищає дітей і тебе. Кожна дитина має ментора: одного працівника, який уважно стежить за цією дитиною і говорить із батьками. Ти хвилюєшся, що в дитини щось не так удома, наприклад синці чи страх? Не розпитуй дитину забагато: скажи керівнику, він знає кроки. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen (AI-correctie 28 nov 2026)
    'c.grouprules.p': "Я хвилююся за цю дитину.", // nieuw, nalezen // nagelezen AI 28 nov
