    'w.opmaken': "застеляти (ліжко)", // nieuw, nalezen // nagelezen AI 28 nov
    's.hotelroom.1': "Я застеляю ліжко чистою білизною.", // nieuw, nalezen // nagelezen AI 28 nov
    's.hotelroom.2': "Поклади два чисті рушники у ванну.", // nieuw, nalezen // nagelezen AI 28 nov
    's.hotelroom.3': "Номер дванадцять готовий. Я йду в тринадцятий.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.q': "Скільки номерів у тебе ще лишилося?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.a': "Ще чотири. Тоді мій список готовий.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom': "Постукай, скажи, хто ти, і зачекай", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.b': "Перш ніж зайти в готельний номер, постукай і скажи, хто ти, наприклад «Housekeeping!». Трохи зачекай і постукай ще раз. На дверях табличка «Niet storen»? Тоді не заходь і запиши це у свій список номерів. Гість у номері? Запитай, чи можна прибрати зараз, або прийди пізніше. Речі гостя лишаються там, де вони є. Гість щось забув? Віднеси це на рецепцію. Ніколи нічого не залишай собі, навіть дрібницю. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.p': "Доброго ранку. Можна мені зараз прибрати номер?", // nieuw, nalezen (AI-correctie 28 nov 2026)
    'c.hotelroom.s': "У порожньому номері ти знаходиш телефон під ліжком. Гість уже виїхав. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.o1': "Віднесеш його на рецепцію.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.o2': "Залишиш собі: гостя вже немає.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.o3': "Залишиш його під ліжком.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.hotelroom.w': "Загублені речі й далі належать гостеві. Рецепція може їх повернути. Залишити їх собі — це крадіжка, і за це можна втратити роботу.", // nieuw, nalezen // nagelezen AI 28 nov
    'l.dosing': "Засоби й машини", // nieuw, nalezen // nagelezen AI 28 nov
    'w.doseren': "дозувати (брати правильну кількість засобу)", // nieuw, nalezen // nagelezen AI 28 nov
