    's.officenight.3': "Я вимикаю світло, коли закінчую.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.q': "Ти сьогодні ввечері працюєш у будівлі наодинці?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.a': "Так. Я напишу тобі, коли закінчу.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight': "Наодинці в будівлі", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.b': "Рано вранці чи пізно ввечері ти часто прибираєш офіс наодинці. Знай, що робити, якщо щось станеться: кому дзвонити і де аптечка? Тримай телефон при собі. Домовся з керівником чи колегою, що ти пишеш повідомлення, коли починаєш і коли закінчуєш. Не впускай нікого, кого не знаєш. Не чіпай папери, екрани чи клавіатури більше, ніж треба для прибирання, і ніколи не читай, що на них. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.p': { m: "Я закінчив і вже йду додому.", f: "Я закінчила і вже йду додому.", x: "Усе зроблено, я вже йду додому." }, // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.s': "Уночі якийсь чоловік стукає у скляні двері. Він каже, що працює тут і забув ключ. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.o1': "Не відчиниш. Подзвониш керівнику.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.o2': "Впустиш його: він виглядає приязно.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.o3': "Даси йому свій ключ.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.officenight.w': "Будь-хто може сказати, що працює там. Керівник може це перевірити. Твоя безпека і будівля — найважливіше.", // nieuw, nalezen // nagelezen AI 28 nov
