    'c.knives.o3': "Зупиниш його ногою.", // nieuw, nalezen // nagelezen AI 28 nov
    'c.knives.w': "Ніж, що падає, може глибоко порізати руку чи ногу. Ніж на підлозі треба лише помити.", // nieuw, nalezen // nagelezen AI 28 nov
