    'w.brandbord': "знак пожежної безпеки (червоний квадрат: тут є вогнегасник або пожежний рукав)", // nieuw, nalezen // nagelezen AI 28 nov
    'w.pictogram': "піктограма (простий малюнок, який щось каже без слів)", // nieuw, nalezen // nagelezen AI 28 nov
